CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, settings_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE members (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','editor','viewer')), created_at TEXT NOT NULL, last_seen_at TEXT);
CREATE TABLE tokens (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, kind TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL, extension_id TEXT, last_seen_at TEXT, revoked_at TEXT);
CREATE TABLE guides (workspace_id TEXT NOT NULL REFERENCES workspaces(id), id TEXT NOT NULL, slug TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, collection_id TEXT, public_id TEXT, is_public INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL, doc_json TEXT NOT NULL, updated_at TEXT NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT, PRIMARY KEY (workspace_id,id));
CREATE INDEX guides_page ON guides(workspace_id, deleted_at, updated_at DESC, id);
CREATE TABLE guide_versions (workspace_id TEXT NOT NULL, guide_id TEXT NOT NULL, version INTEGER NOT NULL, doc_json TEXT NOT NULL, member_id TEXT NOT NULL, summary TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(workspace_id,guide_id,version), FOREIGN KEY(workspace_id,guide_id) REFERENCES guides(workspace_id,id));
CREATE TABLE blobs (key TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, guide_id TEXT NOT NULL, step_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('original','rendered','thumb')), mime TEXT NOT NULL, bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(workspace_id,guide_id) REFERENCES guides(workspace_id,id));
CREATE INDEX blobs_guide ON blobs(workspace_id,guide_id);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), member_id TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL, meta_json TEXT NOT NULL, created_at TEXT NOT NULL);
